ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    "error": {
        "code": "BAD_REQUEST",
        "message": "La requête est invalide",
        "details": error.description,
        "timestamp": now(),
        "correlationId": (vars.correlationId default "")
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "code": "NOT_FOUND",
        "message": "La ressource demandée n'existe pas",
        "details": error.description,
        "timestamp": now(),
        "correlationId": (vars.correlationId default "")
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "code": "METHOD_NOT_ALLOWED",
        "message": "La méthode HTTP n'est pas autorisée pour cette ressource",
        "details": error.description,
        "timestamp": now(),
        "correlationId": (vars.correlationId default "")
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "code": "SERVICE_UNAVAILABLE",
        "message": "Le service externe est temporairement indisponible",
        "details": "Erreur de connexion au service",
        "timestamp": now(),
        "correlationId": (vars.correlationId default "")
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "code": "GATEWAY_TIMEOUT",
        "message": "Le service externe a mis trop de temps à répondre",
        "details": "Le service externe n'a pas répondu dans le délai imparti",
        "timestamp": now(),
        "correlationId": (vars.correlationId default "")
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "code": "TRANSFORMATION_ERROR",
        "message": "Erreur lors de la transformation des données",
        "details": error.description,
        "timestamp": now(),
        "correlationId": (vars.correlationId default "")
    }
}

%dw 2.0
output application/json
---
{
    "error": {
        "code": "INTERNAL_SERVER_ERROR",
        "message": "Une erreur interne s'est produite",
        "details": if (Mule::p('logging.level') == "DEBUG") error.description else "Contactez l'administrateur",
        "timestamp": now(),
        "correlationId": (vars.correlationId default "")
    }
}
